-- 자동 생성 파일 — 수정하지 마세요. src/data/questions.ts 를 고친 뒤
-- `npx tsx scripts/gen-seed.ts` 로 다시 생성하세요.
insert into public.questions
  (id, subject, category, difficulty, stem, choices, answer_index, explanation, sql_steps, tags)
values
  ('q001', 'data_modeling', 'modeling_basics', 1, '데이터 모델링의 3가지 관점(구성요소)에 해당하지 않는 것은?', '["데이터(Entity/Attribute)","프로세스(Process)","데이터와 프로세스의 관계(CRUD)","물리적 저장장치(Storage)"]'::jsonb, 3, '데이터 모델링의 3요소는 ① 데이터(무엇), ② 프로세스(어떻게), ③ 데이터와 프로세스의 상관관계(CRUD 매트릭스)이다. 물리적 저장장치는 모델링 관점이 아니다.', null::jsonb, '["모델링개요","CRUD"]'::jsonb),
  ('q002', 'data_modeling', 'modeling_basics', 2, '다음 중 식별자(Identifier)에 대한 설명으로 옳지 않은 것은?', '["주식별자는 유일성과 최소성을 만족해야 한다.","주식별자는 값이 자주 변경되어도 무방하다.","본질식별자는 업무에 의해 만들어지는 식별자다.","인조식별자는 자연스러운 식별자가 없을 때 인위적으로 부여한다."]'::jsonb, 1, '주식별자의 4대 특징은 유일성·최소성·불변성·존재성이다. 값이 자주 변경되면 불변성에 위배되므로 주식별자로 부적합하다.', null::jsonb, '["식별자","주식별자"]'::jsonb),
  ('q003', 'data_modeling', 'modeling_basics', 2, '정규화에 대한 설명으로 가장 적절한 것은?', '["제1정규형은 부분 함수 종속을 제거한 상태다.","제2정규형은 이행 함수 종속을 제거한 상태다.","제3정규형은 기본키가 아닌 속성 간의 종속(이행 종속)을 제거한 상태다.","정규화를 하면 항상 조회 성능이 향상된다."]'::jsonb, 2, '1NF=속성 원자성, 2NF=부분함수종속 제거, 3NF=이행함수종속 제거. 정규화는 중복을 줄여 저장·정합성에 유리하나, 조인이 늘어 조회 성능은 오히려 나빠질 수 있다.', null::jsonb, '["정규화","함수종속"]'::jsonb),
  ('q004', 'data_modeling', 'modeling_performance', 2, '반정규화(De-normalization)를 고려해야 하는 상황으로 가장 거리가 먼 것은?', '["정규화에 충실했으나 조인이 많아 조회 성능이 심각하게 저하된 경우","대량 범위 처리를 자주 수행해 처리 성능이 느린 경우","특정 통계 계산이 빈번해 매번 집계 비용이 큰 경우","데이터 정합성을 최우선으로 보장해야 하는 경우"]'::jsonb, 3, '반정규화는 조회 성능을 위해 중복을 허용하는 기법으로 정합성 관리 부담이 커진다. 정합성이 최우선이면 반정규화 대상이 아니다.', null::jsonb, '["반정규화","성능"]'::jsonb),
  ('q005', 'data_modeling', 'modeling_performance', 3, '슈퍼타입/서브타입 모델을 물리 테이블로 변환하는 방식 중, 서브타입이 많고 각 서브타입 속성이 매우 다를 때 유리한 방식은?', '["One To One Type (서브타입별 개별 테이블)","Plus Type (슈퍼+서브 분리)","Single Type / All in One (하나의 테이블로 통합)","슈퍼타입 제거 방식"]'::jsonb, 0, '서브타입이 많고 속성이 크게 다르면 One To One(서브타입별 테이블 분리)이 유리하다. 반대로 서브타입이 적고 트랜잭션이 통합적이면 All in One이 유리하다.', null::jsonb, '["슈퍼타입","서브타입","물리모델"]'::jsonb),
  ('q006', 'data_modeling', 'modeling_performance', 2, '관계형 DB에서 NULL에 대한 설명으로 옳은 것은?', '["NULL은 공백(space) 또는 0과 같다.","COUNT(*)는 NULL이 포함된 행을 제외하고 센다.","NULL과의 산술 연산 결과는 NULL이다.","NULL은 인덱스에 항상 저장된다."]'::jsonb, 2, 'NULL은 ''알 수 없음''이며 0/공백과 다르다. NULL과의 산술 연산·비교 결과는 NULL(UNKNOWN)이다. COUNT(*)는 행 수를 세므로 NULL 행도 포함, COUNT(칼럼)은 NULL 제외.', null::jsonb, '["NULL"]'::jsonb),
  ('q007', 'sql', 'sql_basics', 1, 'SQL 문장의 논리적 실행(처리) 순서를 올바르게 나열한 것은?', '["SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY","FROM → WHERE → GROUP BY → HAVING → SELECT → ORDER BY","FROM → GROUP BY → WHERE → HAVING → SELECT → ORDER BY","WHERE → FROM → GROUP BY → SELECT → HAVING → ORDER BY"]'::jsonb, 1, '논리적 실행 순서: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → ORDER BY. 작성 순서(SELECT 먼저)와 다르다는 점이 핵심.', null::jsonb, '["실행순서"]'::jsonb),
  ('q008', 'sql', 'sql_basics', 2, 'NULL 처리 함수에 대한 설명으로 옳지 않은 것은?', '["NVL(expr1, expr2)는 expr1이 NULL이면 expr2를 반환한다.","NULLIF(a, b)는 a=b이면 NULL, 아니면 a를 반환한다.","COALESCE는 인자 중 첫 번째 NOT NULL 값을 반환한다.","NVL2(expr1, a, b)는 expr1이 NULL이면 a를 반환한다."]'::jsonb, 3, 'NVL2(expr1, a, b)는 expr1이 NOT NULL이면 a, NULL이면 b를 반환한다. 보기 설명은 반대로 되어 있다.', null::jsonb, '["NULL함수","NVL","COALESCE"]'::jsonb),
  ('q009', 'sql', 'sql_basics', 2, 'WHERE 절에서 sal 컬럼에 NULL이 들어 있는 행을 조회하려 한다. 올바른 조건은?', '["WHERE sal = NULL","WHERE sal != NULL","WHERE sal IS NULL","WHERE sal <> ''''"]'::jsonb, 2, 'NULL은 =/!= 로 비교할 수 없다(결과가 UNKNOWN). 반드시 IS NULL / IS NOT NULL 을 사용한다.', null::jsonb, '["NULL","WHERE"]'::jsonb),
  ('q010', 'sql', 'sql_basics', 2, '다음 쿼리의 단계별 결과를 참고할 때 최종 출력 행 수는? (아래 ''단계별 결과'' 참고)', '["1행","2행","3행","4행"]'::jsonb, 1, 'WHERE sal>=250 으로 3행이 남고, GROUP BY dept 로 부서별 그룹, HAVING COUNT(*)>=2 로 인원 2명 이상 부서만 남긴다. 최종 2개 부서(SALES, DEV) → 2행.', '{"query":"SELECT dept, COUNT(*) AS cnt FROM emp WHERE sal >= 250 GROUP BY dept HAVING COUNT(*) >= 2 ORDER BY cnt DESC","steps":[{"clause":"FROM / JOIN","desc":"emp 테이블 전체를 읽는다.","table":{"columns":["name","dept","sal"],"data":[["Kim","SALES",300],["Lee","SALES",250],["Park","DEV",400],["Choi","DEV",260],["Yun","HR",220],["Han","DEV",240]]}},{"clause":"WHERE","desc":"sal >= 250 인 행만 남긴다. (Yun 220, Han 240 제거)","table":{"columns":["name","dept","sal"],"data":[["Kim","SALES",300],["Lee","SALES",250],["Park","DEV",400],["Choi","DEV",260]]}},{"clause":"GROUP BY","desc":"dept 기준으로 그룹핑한다.","table":{"columns":["dept","members"],"data":[["SALES","Kim, Lee"],["DEV","Park, Choi"]]}},{"clause":"HAVING","desc":"COUNT(*) >= 2 인 그룹만 남긴다. (둘 다 2명이라 유지)","table":{"columns":["dept","cnt"],"data":[["SALES",2],["DEV",2]]}},{"clause":"SELECT","desc":"dept, COUNT(*) AS cnt 를 출력한다.","table":{"columns":["dept","cnt"],"data":[["SALES",2],["DEV",2]]}},{"clause":"ORDER BY","desc":"cnt 내림차순 정렬 (동률이라 순서 유지).","table":{"columns":["dept","cnt"],"data":[["SALES",2],["DEV",2]]}}]}'::jsonb, '["GROUP BY","HAVING","실행순서"]'::jsonb),
  ('q011', 'sql', 'sql_basics', 1, '다음 중 집계 함수(Aggregate Function)와 그룹 처리에 대한 설명으로 옳은 것은?', '["WHERE 절에서 집계함수 조건을 사용할 수 있다.","GROUP BY 에 없는 일반 컬럼도 SELECT 절에 자유롭게 쓸 수 있다.","HAVING 절은 그룹핑 후의 집계 결과에 조건을 건다.","COUNT(칼럼)은 NULL도 포함하여 센다."]'::jsonb, 2, '집계 조건은 HAVING(그룹 후)에서 건다. GROUP BY 미포함 일반컬럼은 SELECT에 못 쓴다. COUNT(칼럼)은 NULL 제외, COUNT(*)만 전체 행을 센다.', null::jsonb, '["집계함수","HAVING","GROUP BY"]'::jsonb),
  ('q012', 'sql', 'sql_advanced', 2, '다음 조인 결과를 참고할 때, INNER JOIN 결과 행 수는? (단계별 결과 참고)', '["2행","3행","4행","5행"]'::jsonb, 1, 'dept.id 와 emp.dept_id 가 일치하는 행만 결합된다. HR(30)에 속한 사원이 없고, dept_id가 NULL/미매칭인 사원은 제외되어 3행이 남는다.', '{"query":"SELECT e.name, d.dname FROM emp e INNER JOIN dept d ON e.dept_id = d.id","steps":[{"clause":"FROM / JOIN","desc":"emp(왼쪽), dept(오른쪽) 두 테이블을 준비한다.","table":{"columns":["emp.name","emp.dept_id","dept.id","dept.dname"],"data":[["Kim",10,10,"SALES"],["Lee",20,20,"DEV"],["Park",20,30,"HR"],["Choi",null,"-","-"]]}},{"clause":"ON (JOIN 조건)","desc":"e.dept_id = d.id 로 매칭되는 조합만 남긴다. Choi(NULL)와 HR(30)은 짝이 없어 탈락.","table":{"columns":["name","dept_id","dname"],"data":[["Kim",10,"SALES"],["Lee",20,"DEV"],["Park",20,"DEV"]]}},{"clause":"SELECT","desc":"e.name, d.dname 출력 → 3행.","table":{"columns":["name","dname"],"data":[["Kim","SALES"],["Lee","DEV"],["Park","DEV"]]}}]}'::jsonb, '["JOIN","INNER JOIN"]'::jsonb),
  ('q013', 'sql', 'sql_advanced', 3, '다음 중 OUTER JOIN에 대한 설명으로 옳지 않은 것은?', '["LEFT OUTER JOIN은 왼쪽 테이블의 모든 행을 보존한다.","매칭되지 않는 쪽의 컬럼은 NULL로 채워진다.","FULL OUTER JOIN은 양쪽의 매칭 안 되는 행을 모두 보존한다.","OUTER JOIN 결과 행 수는 항상 INNER JOIN보다 적다."]'::jsonb, 3, 'OUTER JOIN은 매칭 안 되는 행까지 보존하므로 결과 행 수가 INNER JOIN보다 크거나 같다. ''항상 적다''는 틀린 설명.', null::jsonb, '["OUTER JOIN"]'::jsonb),
  ('q014', 'sql', 'sql_advanced', 3, '윈도우 함수 ROW_NUMBER(), RANK(), DENSE_RANK()에 대한 설명으로 옳은 것은?', '["값이 동일하면 세 함수 모두 같은 번호를 부여한다.","RANK()는 동순위 뒤 순위를 건너뛰고, DENSE_RANK()는 건너뛰지 않는다.","ROW_NUMBER()는 동순위에 같은 번호를 준다.","DENSE_RANK()는 동순위 뒤 순위를 건너뛴다."]'::jsonb, 1, '동일 값(예: 100,100,90)에서 RANK는 1,1,3(건너뜀), DENSE_RANK는 1,1,2(안 건너뜀), ROW_NUMBER는 1,2,3(무조건 유일 번호).', null::jsonb, '["윈도우함수","RANK","ROW_NUMBER"]'::jsonb),
  ('q015', 'sql', 'sql_advanced', 2, '집합 연산자에 대한 설명으로 옳지 않은 것은?', '["UNION은 중복을 제거하고 정렬 부하가 있을 수 있다.","UNION ALL은 중복을 제거하지 않고 그대로 합친다.","INTERSECT는 두 집합의 교집합을 반환한다.","MINUS(EXCEPT)는 두 집합의 합집합을 반환한다."]'::jsonb, 3, 'MINUS(EXCEPT)는 첫 집합에서 두 번째 집합을 뺀 ''차집합''을 반환한다. 합집합은 UNION이다.', null::jsonb, '["집합연산","UNION","MINUS"]'::jsonb),
  ('q016', 'sql', 'sql_advanced', 3, '다음 계층형 질의(CONNECT BY)에서 START WITH 와 CONNECT BY PRIOR의 역할로 옳은 것은?', '["START WITH는 전개 방향을, CONNECT BY는 루트 행을 지정한다.","START WITH는 루트(시작) 행을, CONNECT BY PRIOR는 부모-자식 전개 규칙을 지정한다.","둘 다 정렬을 담당한다.","CONNECT BY는 중복 제거를 담당한다."]'::jsonb, 1, 'START WITH = 계층 전개의 루트 행 지정, CONNECT BY PRIOR = 부모-자식 관계(전개 규칙) 지정. LEVEL 의사컬럼으로 깊이를 알 수 있다.', null::jsonb, '["계층형질의","CONNECT BY"]'::jsonb),
  ('q017', 'sql', 'sql_advanced', 2, '스칼라 서브쿼리(Scalar Subquery)에 대한 설명으로 옳은 것은?', '["SELECT 절에 위치하며 한 행·한 컬럼(단일 값)을 반환해야 한다.","여러 행을 반환해도 오류가 나지 않는다.","FROM 절에서만 사용할 수 있다.","메인쿼리 컬럼을 참조할 수 없다."]'::jsonb, 0, '스칼라 서브쿼리는 SELECT 절 등에서 단일 값(1행 1컬럼)을 반환해야 하며, 2행 이상 반환 시 오류. 메인쿼리 컬럼 참조(상관 서브쿼리) 가능.', null::jsonb, '["서브쿼리","스칼라서브쿼리"]'::jsonb),
  ('q018', 'sql', 'sql_management', 2, 'DDL/DML/TCL 분류로 옳은 것은?', '["TRUNCATE는 DML이며 ROLLBACK으로 복구할 수 있다.","TRUNCATE는 DDL이며 자동 커밋되어 ROLLBACK이 불가하다.","DELETE는 DDL이다.","COMMIT은 DDL이다."]'::jsonb, 1, 'TRUNCATE는 DDL로 즉시 자동 커밋되어 ROLLBACK 불가하며 저장공간을 반납한다. DELETE는 DML이라 ROLLBACK 가능. COMMIT/ROLLBACK은 TCL.', null::jsonb, '["DDL","TRUNCATE","DELETE"]'::jsonb),
  ('q019', 'sql', 'sql_management', 2, '제약조건(Constraint)에 대한 설명으로 옳지 않은 것은?', '["PRIMARY KEY는 UNIQUE + NOT NULL 성질을 가진다.","FOREIGN KEY는 참조 무결성을 보장한다.","UNIQUE 제약이 걸린 컬럼에는 NULL을 절대 넣을 수 없다.","CHECK 제약은 컬럼 값의 범위·조건을 제한한다."]'::jsonb, 2, 'UNIQUE는 중복만 막을 뿐 NULL은 (일반적으로 여러 개) 허용된다. NOT NULL을 함께 걸어야 NULL을 막는다.', null::jsonb, '["제약조건","UNIQUE","PK"]'::jsonb),
  ('q020', 'sql', 'sql_management', 3, '권한 관리 명령에 대한 설명으로 옳은 것은?', '["GRANT는 권한을 회수하는 명령이다.","REVOKE는 권한을 부여하는 명령이다.","ROLE은 여러 권한을 묶어 관리하는 객체다.","WITH GRANT OPTION은 권한을 절대 재부여하지 못하게 한다."]'::jsonb, 2, 'GRANT=부여, REVOKE=회수, ROLE=권한 묶음. WITH GRANT OPTION은 부여받은 사용자가 다시 다른 사용자에게 권한을 줄 수 있게 한다.', null::jsonb, '["권한","GRANT","ROLE"]'::jsonb),
  ('q021', 'data_modeling', 'modeling_basics', 2, '데이터베이스 3단계 스키마와 데이터 독립성에 대한 설명으로 옳지 않은 것은?', '["외부 스키마는 사용자·응용프로그램 관점의 뷰로 여러 개 존재한다.","개념 스키마는 조직 전체 관점에서 통합한 논리 구조다.","내부 스키마는 데이터가 실제로 저장되는 물리 구조를 정의한다.","논리적 독립성은 내부 스키마가 변경되어도 개념 스키마에 영향이 없는 것이다."]'::jsonb, 3, '논리적 독립성 = 개념 스키마가 바뀌어도 외부 스키마에 영향 없음. 물리적 독립성 = 내부 스키마가 바뀌어도 개념/외부 스키마에 영향 없음. 보기 4는 물리적 독립성 설명이다.', null::jsonb, '["3층스키마","데이터독립성"]'::jsonb),
  ('q022', 'data_modeling', 'modeling_basics', 2, '발생 시점에 따른 엔터티 분류에 대한 설명으로 옳은 것은?', '["기본엔터티는 다른 엔터티로부터 파생되어 생성된다.","중심엔터티는 기본엔터티로부터 발생하며 업무의 중심 역할을 한다.","행위엔터티는 독립적으로 생성되며 자신만의 고유 식별자를 갖는다.","기본엔터티는 2개 이상의 부모 엔터티로부터 발생한다."]'::jsonb, 1, '기본엔터티(독립 생성·부모 역할), 중심엔터티(기본에서 파생, 업무 중심·데이터 많음), 행위엔터티(2개 이상 부모에서 파생). 옳은 것은 보기 2뿐이다.', null::jsonb, '["엔터티분류","발생시점"]'::jsonb),
  ('q023', 'data_modeling', 'modeling_basics', 2, '속성을 특성에 따라 분류할 때 ''파생 속성''에 대한 설명으로 옳은 것은?', '["업무 분석으로 바로 도출되는 가장 일반적인 속성이다.","다른 속성값을 계산하거나 특정 규칙으로 변형하여 만든 속성이다(예: 합계, 평균).","업무에 원래 없지만 설계상 필요해 새로 만든 속성이다.","PK, FK에 속하지 않는 모든 속성이다."]'::jsonb, 1, '기본/설계/파생. 파생 속성은 계산·가공된 값(합계·평균·이자 등)으로 정합성 유지를 위해 최소화가 권장된다. 보기 1=기본, 3=설계, 4=일반 속성.', null::jsonb, '["속성분류","파생속성"]'::jsonb),
  ('q024', 'data_modeling', 'modeling_basics', 2, '엔터티 간 관계에 대한 설명으로 옳지 않은 것은?', '["관계차수는 1:1, 1:M, M:N으로 표현한다.","관계선택사양은 필수참여와 선택참여로 구분한다.","M:N 관계는 그대로 두는 것이 물리 모델 구현에 유리하다.","관계명은 애매한 동사를 피하고 현재형으로 표현한다."]'::jsonb, 2, 'M:N 관계는 대개 교차(연관) 엔터티를 두어 1:M 관계 두 개로 해소해야 물리 구현이 수월하다. 그대로 두면 구현이 어렵다.', null::jsonb, '["관계","관계차수"]'::jsonb),
  ('q025', 'data_modeling', 'modeling_basics', 2, '식별자 분류에 대한 설명으로 옳지 않은 것은?', '["주식별자는 유일성·최소성·불변성·존재성을 만족한다.","외부식별자는 다른 엔터티로부터 참조되어 온 식별자다.","복합식별자는 두 개 이상의 속성으로 구성된다.","인조(대리)식별자는 업무에 원래 존재하는 자연 식별자다."]'::jsonb, 3, '인조(대리)식별자는 자연 식별자가 없거나 복잡할 때 인위적으로 부여한 식별자다. 업무에 원래 존재하는 것은 본질(원조)식별자다.', null::jsonb, '["식별자분류","인조식별자"]'::jsonb),
  ('q026', 'data_modeling', 'modeling_basics', 2, '정규화가 되지 않아 발생하는 이상현상(Anomaly)에 대한 설명으로 옳지 않은 것은?', '["삽입이상: 원치 않는 데이터가 함께 삽입되거나 특정 속성 없이는 삽입이 어려운 현상","갱신이상: 중복 데이터 중 일부만 수정되어 일관성이 깨지는 현상","삭제이상: 행 삭제 시 함께 보관되던 다른 정보까지 연쇄 삭제되는 현상","이상현상은 반정규화를 통해 제거한다."]'::jsonb, 3, '이상현상(삽입·갱신·삭제)은 정규화로 제거한다. 반정규화는 오히려 중복을 허용하는 반대 개념이다.', null::jsonb, '["이상현상","정규화"]'::jsonb),
  ('q027', 'data_modeling', 'modeling_performance', 2, '반정규화(De-normalization) 기법에 대한 설명으로 옳지 않은 것은?', '["테이블 병합: 1:1 또는 1:M 관계 테이블을 합쳐 조인을 줄인다.","수직 분할: 자주 쓰는 컬럼과 그렇지 않은 컬럼을 1:1로 분리한다.","중복 컬럼 추가: 조인을 줄이기 위해 다른 테이블의 컬럼을 복제한다.","반정규화는 조회 성능을 높이면서 입력·수정·삭제 성능과 정합성 관리도 함께 쉬워진다."]'::jsonb, 3, '반정규화는 조회 성능은 향상되지만 중복으로 인해 입력·수정·삭제 부담이 커지고 정합성 관리가 어려워진다.', null::jsonb, '["반정규화"]'::jsonb),
  ('q028', 'data_modeling', 'modeling_performance', 3, '식별자 관계와 비식별자 관계에 대한 설명으로 옳은 것은?', '["식별자 관계는 부모의 식별자가 자식의 일반 속성으로 상속된다.","비식별자 관계는 실선으로 표기한다.","식별자 관계는 부모의 식별자가 자식의 주식별자로 상속되며 강한 연결이다.","비식별자 관계에서는 조인이 전혀 발생하지 않는다."]'::jsonb, 2, '식별자 관계=부모 PK가 자식 PK로 상속(실선·강한 관계, PK가 복잡해질 수 있음). 비식별자 관계=부모 PK가 자식의 일반 속성으로(점선·약한 관계, 과도한 조인 유발 가능).', null::jsonb, '["식별자관계","비식별자관계"]'::jsonb),
  ('q029', 'data_modeling', 'modeling_performance', 2, '트랜잭션의 ACID 특성 중 ''고립성(Isolation)''에 대한 설명으로 옳은 것은?', '["트랜잭션의 연산은 모두 성공하거나 모두 실패한다.","실행 중인 트랜잭션의 중간 결과에 다른 트랜잭션이 접근할 수 없다.","트랜잭션이 성공하면 결과가 영구적으로 저장된다.","실행 전후로 데이터베이스가 일관된 상태를 유지한다."]'::jsonb, 1, '원자성(보기1), 고립성(보기2), 지속성(보기3), 일관성(보기4). 고립성은 동시에 실행되는 트랜잭션들이 서로의 중간 결과에 간섭하지 못하게 한다.', null::jsonb, '["트랜잭션","ACID"]'::jsonb),
  ('q030', 'data_modeling', 'modeling_performance', 3, '함수적 종속성에 대한 설명으로 옳지 않은 것은?', '["완전 함수 종속: 일반 속성이 기본키 ''전체''에 종속된다.","부분 함수 종속: 일반 속성이 복합 기본키의 ''일부''에만 종속된다.","이행 함수 종속: A→B, B→C일 때 A→C가 성립하는 종속이다.","제2정규형은 이행 함수 종속을 제거한 것이다."]'::jsonb, 3, '제2정규형은 부분 함수 종속을 제거한 것이고, 이행 함수 종속을 제거한 것은 제3정규형이다.', null::jsonb, '["함수종속","정규형"]'::jsonb),
  ('q031', 'sql', 'sql_basics', 2, 'Oracle에서 SUBSTR(''SQLD-2026'', 6, 4) 의 결과로 옳은 것은?', '["SQLD","2026","-202","D-20"]'::jsonb, 1, 'SUBSTR(문자열, 시작위치, 길이). 위치는 1부터 시작하며 6번째 문자는 ''2''. 거기서 4글자 → ''2026''.', null::jsonb, '["문자함수","SUBSTR"]'::jsonb),
  ('q032', 'sql', 'sql_basics', 2, '다음 숫자 함수 결과 중 옳지 않은 것은? (Oracle 기준)', '["ROUND(123.456, 1) = 123.5","TRUNC(123.456, 1) = 123.4","MOD(10, 3) = 1","CEIL(-1.5) = -2"]'::jsonb, 3, 'CEIL은 ''올림''이므로 -1.5의 올림은 -1이다(-2는 FLOOR). ROUND(반올림), TRUNC(버림), MOD(나머지)는 모두 옳다.', null::jsonb, '["숫자함수","CEIL","MOD"]'::jsonb),
  ('q033', 'sql', 'sql_basics', 2, 'NULL 연산에 대한 설명으로 옳은 것은?', '["SELECT 100 + NULL 의 결과는 100이다.","SUM은 NULL을 0으로 바꾼 뒤 더한다.","COUNT(*)는 NULL이 포함된 행도 세지만, COUNT(컬럼)은 NULL을 제외한다.","AVG(컬럼)은 NULL을 0으로 간주하여 평균을 낸다."]'::jsonb, 2, '행 내 산술(가로 연산)에 NULL이 있으면 결과는 NULL(0 아님). 집계(세로 연산)는 NULL을 ''제외''하고 계산한다(0으로 치환하지 않음). COUNT(*)만 전체 행을 센다.', null::jsonb, '["NULL","COUNT","집계함수"]'::jsonb),
  ('q034', 'sql', 'sql_basics', 2, '다음 CASE 식과 동일한 Oracle DECODE 표현은?
CASE WHEN grade=''A'' THEN 1 WHEN grade=''B'' THEN 2 ELSE 0 END', '["DECODE(grade, ''A'', 1, ''B'', 2, 0)","DECODE(grade, 1, ''A'', 2, ''B'', 0)","DECODE(grade, ''A'', ''B'', 1, 2, 0)","NVL(grade, ''A'', 1)"]'::jsonb, 0, 'DECODE(기준값, 값1, 결과1, 값2, 결과2, 기본값). 단 DECODE는 ''='' 비교만 가능하고, CASE는 범위 조건(>, < 등)도 표현할 수 있다.', null::jsonb, '["CASE","DECODE"]'::jsonb),
  ('q035', 'sql', 'sql_basics', 2, 'WHERE 절 조건 ''A OR B AND C'' 는 어떻게 해석되는가?', '["(A OR B) AND C","A OR (B AND C)","왼쪽부터 순서대로 평가되어 (A OR B) AND C","우선순위가 없어 문법 오류가 난다"]'::jsonb, 1, 'AND가 OR보다 우선순위가 높다. 따라서 A OR (B AND C)로 해석된다. (A OR B) AND C를 의도하면 괄호가 필요하다.', null::jsonb, '["연산자우선순위","AND","OR"]'::jsonb),
  ('q036', 'sql', 'sql_basics', 2, '이름이 ''김''으로 시작하고 정확히 3글자인 사원을 찾는 조건으로 옳은 것은? (Oracle)', '["WHERE name LIKE ''김%''","WHERE name LIKE ''김__''","WHERE name LIKE ''김_''","WHERE name = ''김%%''"]'::jsonb, 1, '%는 0글자 이상, _는 정확히 한 글자를 의미한다. ''김'' + 언더스코어 2개 → ''김''으로 시작하는 3글자.', null::jsonb, '["LIKE","와일드카드"]'::jsonb),
  ('q037', 'sql', 'sql_basics', 1, 'WHERE score BETWEEN 60 AND 80 과 동일한 조건은?', '["score > 60 AND score < 80","score >= 60 AND score <= 80","score >= 60 OR score <= 80","score IN (60, 80)"]'::jsonb, 1, 'BETWEEN a AND b는 경계값을 포함한다(a ≤ x ≤ b). 즉 60과 80도 포함된다.', null::jsonb, '["BETWEEN","WHERE"]'::jsonb),
  ('q038', 'sql', 'sql_basics', 2, 'comm 컬럼에 NULL이 3개 포함된 총 10행 테이블에서 SELECT COUNT(comm) FROM emp 의 결과는?', '["10","7","3","0"]'::jsonb, 1, 'COUNT(컬럼)은 NULL을 제외하고 센다. 10행 중 NULL 3개를 빼면 7. (COUNT(*)였다면 10.)', null::jsonb, '["COUNT","NULL"]'::jsonb),
  ('q039', 'sql', 'sql_basics', 3, 'SELECT 절에서 정의한 컬럼 별칭(ALIAS)을 사용할 수 있는 절은?', '["WHERE","GROUP BY","HAVING","ORDER BY"]'::jsonb, 3, '실행 순서상 SELECT는 ORDER BY 바로 앞에서 수행된다. 따라서 별칭은 그 뒤에 실행되는 ORDER BY에서만 쓸 수 있고, 먼저 실행되는 WHERE/GROUP BY/HAVING에서는 쓸 수 없다.', null::jsonb, '["ALIAS","실행순서","ORDER BY"]'::jsonb),
  ('q040', 'sql', 'sql_basics', 2, 'SELECT DISTINCT dept, job FROM emp 에 대한 설명으로 옳은 것은?', '["dept 컬럼만 중복을 제거한다.","dept와 job의 ''조합''이 중복인 행을 제거한다.","문법 오류다.","job 컬럼만 중복을 제거한다."]'::jsonb, 1, 'DISTINCT는 SELECT 절에 나열된 모든 컬럼의 ''조합''을 기준으로 중복을 제거한다.', null::jsonb, '["DISTINCT"]'::jsonb),
  ('q041', 'sql', 'sql_basics', 2, '부서별 평균 급여가 300 이상인 부서만 조회할 때 올바른 방법은?', '["WHERE AVG(sal) >= 300 으로 필터한다.","GROUP BY dept 뒤 HAVING AVG(sal) >= 300 으로 필터한다.","SELECT 절에서 AVG 조건을 건다.","ORDER BY AVG(sal) >= 300 으로 필터한다."]'::jsonb, 1, '그룹핑 후 집계 결과에 대한 조건은 HAVING에서 건다. WHERE 절에는 집계함수를 사용할 수 없다.', null::jsonb, '["HAVING","GROUP BY","집계함수"]'::jsonb),
  ('q042', 'sql', 'sql_basics', 2, 'Oracle에서 세 문자열 ''A'', ''B'', ''C''를 연결하는 올바른 표현은?', '["''A'' + ''B'' + ''C''","CONCAT(''A'', ''B'', ''C'')","''A'' || ''B'' || ''C''","''A'' & ''B'' & ''C''"]'::jsonb, 2, 'Oracle의 합성(연결) 연산자는 ||이다. + 연결은 SQL Server 방식이고, Oracle CONCAT은 인자를 2개만 받으므로 3개는 불가.', null::jsonb, '["합성연산자","CONCAT"]'::jsonb),
  ('q043', 'sql', 'sql_advanced', 2, 'CROSS JOIN(카티션 곱, Cartesian Product)에 대한 설명으로 옳은 것은?', '["두 테이블의 공통 컬럼으로 자동 조인한다.","두 테이블 행의 모든 조합을 반환하며, m행과 n행이면 m×n행이 된다.","조인 조건에 맞는 행만 반환한다.","왼쪽 테이블의 모든 행을 보존한다."]'::jsonb, 1, 'CROSS JOIN은 조인 조건 없이 두 테이블 행의 모든 조합(m×n행)을 만든다.', null::jsonb, '["CROSS JOIN","카티션곱"]'::jsonb),
  ('q044', 'sql', 'sql_advanced', 3, 'NATURAL JOIN에 대한 설명으로 옳지 않은 것은?', '["이름과 타입이 같은 컬럼을 자동으로 조인 조건에 사용한다.","조인에 사용된 컬럼에는 테이블명 접두사를 붙이면 안 된다.","ON 절이나 USING 절을 반드시 함께 명시해야 한다.","공통 컬럼은 결과에 한 번만 표시된다."]'::jsonb, 2, 'NATURAL JOIN은 같은 이름의 컬럼으로 자동 조인하므로 ON/USING 절을 함께 쓸 수 없다(문법 오류).', null::jsonb, '["NATURAL JOIN"]'::jsonb),
  ('q045', 'sql', 'sql_advanced', 2, '셀프 조인(Self Join)에 대한 설명으로 옳은 것은?', '["서로 다른 두 테이블을 조인하는 것이다.","하나의 테이블을 자기 자신과 조인하며, 반드시 별칭(ALIAS)을 사용한다.","별칭 없이도 컬럼 구분이 가능하다.","OUTER JOIN에서만 사용할 수 있다."]'::jsonb, 1, '셀프 조인은 동일 테이블을 두 개인 것처럼(예: e1, e2) 별칭을 붙여 조인한다. 사원-관리자 같은 계층 표현에 쓰인다.', null::jsonb, '["SELF JOIN"]'::jsonb),
  ('q046', 'sql', 'sql_advanced', 3, '서브쿼리에 대한 설명으로 옳지 않은 것은?', '["스칼라 서브쿼리는 SELECT 절에 위치하며 단일 값을 반환한다.","인라인 뷰는 FROM 절에 위치한다.","중첩 서브쿼리는 WHERE·HAVING 절에 위치한다.","연관(상관) 서브쿼리는 메인쿼리와 독립적으로 한 번만 실행된다."]'::jsonb, 3, '연관(상관) 서브쿼리는 메인쿼리의 컬럼을 참조하며 메인쿼리의 각 행마다 반복 실행된다. 독립적으로 한 번만 실행되는 것은 비연관 서브쿼리다.', null::jsonb, '["서브쿼리","연관서브쿼리"]'::jsonb),
  ('q047', 'sql', 'sql_advanced', 3, 'WHERE sal > ALL (SELECT sal FROM emp WHERE dept=''SALES'') 의 의미로 옳은 것은?', '["SALES 부서 급여 중 최댓값보다 커야 참이 된다.","SALES 부서 급여 중 최솟값보다 크면 참이 된다.","SALES 부서 평균 급여보다 커야 참이 된다.","SALES 부서 급여 중 하나와 같으면 참이 된다."]'::jsonb, 0, '> ALL(집합)은 집합의 모든 값보다 커야 하므로 ''최댓값''보다 커야 한다. 반대로 > ANY는 ''최솟값''보다 크면 참이다.', null::jsonb, '["서브쿼리","ALL","ANY"]'::jsonb),
  ('q048', 'sql', 'sql_advanced', 2, 'EXISTS 서브쿼리에 대한 설명으로 옳은 것은?', '["서브쿼리가 반환하는 값을 메인쿼리 컬럼과 크기 비교한다.","서브쿼리 결과 행이 존재하는지 여부(참/거짓)만 판단한다.","반드시 단일 값을 반환해야 한다.","IN보다 항상 느리다."]'::jsonb, 1, 'EXISTS는 서브쿼리에 결과 행이 하나라도 존재하는지(참/거짓)만 확인하며, 실제 값은 비교하지 않는다.', null::jsonb, '["EXISTS","서브쿼리"]'::jsonb),
  ('q049', 'sql', 'sql_advanced', 2, '집합 연산자에 대한 설명으로 옳지 않은 것은?', '["UNION은 중복을 제거하며 정렬이 수반될 수 있다.","UNION ALL은 중복을 제거하지 않고 그대로 합친다.","INTERSECT는 두 집합에 공통으로 존재하는 행을 반환한다.","UNION ALL은 두 SELECT의 컬럼 개수가 달라도 실행된다."]'::jsonb, 3, '집합 연산은 두 SELECT의 컬럼 개수와 데이터 타입이 호환되어야 한다. 개수가 다르면 오류가 난다.', null::jsonb, '["집합연산","UNION"]'::jsonb),
  ('q050', 'sql', 'sql_advanced', 3, 'GROUP BY ROLLUP(dept, job) 에 대한 설명으로 옳은 것은?', '["dept와 job의 가능한 모든 조합 소계를 만든다(CUBE와 동일).","(dept, job) → (dept) → () 순의 소계와 총계를 생성한다.","소계 없이 그룹 결과만 반환한다.","job별 소계만 생성한다."]'::jsonb, 1, 'ROLLUP(A,B)는 (A,B)→(A)→() 순의 계층적(일방향) 소계와 총계를 만든다. CUBE(A,B)는 (A,B),(A),(B),()의 모든 조합 소계를 만든다.', null::jsonb, '["ROLLUP","CUBE","그룹함수"]'::jsonb),
  ('q051', 'sql', 'sql_advanced', 2, '윈도우 함수 LAG와 LEAD에 대한 설명으로 옳은 것은?', '["LAG는 현재 행 기준 다음(뒤) 행 값을 가져온다.","LEAD는 현재 행 기준 이전(앞) 행 값을 가져온다.","LAG는 이전(앞) 행, LEAD는 다음(뒤) 행의 값을 가져온다.","둘 다 PARTITION BY와 함께 쓸 수 없다."]'::jsonb, 2, 'LAG는 현재 행보다 앞선(이전) 행, LEAD는 뒤(다음) 행의 값을 참조한다. 둘 다 PARTITION BY·ORDER BY와 함께 사용한다.', null::jsonb, '["윈도우함수","LAG","LEAD"]'::jsonb),
  ('q052', 'sql', 'sql_advanced', 3, '윈도우 함수에 대한 설명으로 옳지 않은 것은?', '["NTILE(4)는 데이터를 4개 그룹으로 균등 분할한다.","RATIO_TO_REPORT는 파티션 합계 대비 비율을 반환한다.","ROW_NUMBER는 동일 값에도 서로 다른 고유 순번을 부여한다.","PARTITION BY는 GROUP BY처럼 결과 행 수를 줄인다."]'::jsonb, 3, '윈도우 함수는 행을 줄이지 않고 각 행에 계산 결과를 덧붙인다. PARTITION BY는 계산 대상 그룹만 나눌 뿐 행 수를 유지한다(GROUP BY와 다른 점).', null::jsonb, '["윈도우함수","NTILE","PARTITION BY"]'::jsonb),
  ('q053', 'sql', 'sql_advanced', 3, 'Oracle에서 급여 상위 3명을 구하는 올바른 쿼리는?', '["SELECT * FROM emp WHERE ROWNUM <= 3 ORDER BY sal DESC","SELECT * FROM (SELECT * FROM emp ORDER BY sal DESC) WHERE ROWNUM <= 3","SELECT * FROM emp ORDER BY sal DESC WHERE ROWNUM <= 3","SELECT TOP 3 * FROM emp ORDER BY sal DESC"]'::jsonb, 1, 'ROWNUM은 ORDER BY보다 먼저 부여되므로, 먼저 정렬한 인라인 뷰를 만든 뒤 바깥에서 ROWNUM으로 잘라야 한다. 보기 1은 정렬 전에 3행을 잘라 오답이고, TOP은 SQL Server 문법이다.', null::jsonb, '["ROWNUM","TOP-N","인라인뷰"]'::jsonb),
  ('q054', 'sql', 'sql_advanced', 3, '계층형 질의(CONNECT BY)의 의사컬럼·함수에 대한 설명으로 옳지 않은 것은?', '["LEVEL은 계층의 깊이를 나타내며 루트는 1이다.","CONNECT_BY_ISLEAF는 최하위(잎) 노드이면 1을 반환한다.","SYS_CONNECT_BY_PATH는 루트부터 현재까지의 경로를 반환한다.","START WITH는 부모-자식 전개 규칙을 지정한다."]'::jsonb, 3, 'START WITH는 전개의 시작(루트) 행을 지정한다. 부모-자식 전개 규칙은 CONNECT BY PRIOR가 담당한다.', null::jsonb, '["계층쿼리","CONNECT BY","LEVEL"]'::jsonb),
  ('q055', 'sql', 'sql_management', 2, 'MERGE 문에 대한 설명으로 옳은 것은?', '["조건에 맞으면 INSERT만, 안 맞으면 UPDATE만 수행한다.","한 문장으로 조건에 따라 UPDATE(MATCHED)와 INSERT(NOT MATCHED)를 함께 처리한다.","DELETE는 절대 포함할 수 없다.","소스 테이블 없이 단독으로 사용한다."]'::jsonb, 1, 'MERGE는 소스와 타깃을 ON 조건으로 비교해, 일치하면 UPDATE, 없으면 INSERT를 한 번에 수행한다(입력·수정 동시 처리).', null::jsonb, '["MERGE","DML"]'::jsonb),
  ('q056', 'sql', 'sql_management', 2, '트랜잭션 제어(TCL)에 대한 설명으로 옳지 않은 것은?', '["COMMIT은 변경사항을 확정한다.","ROLLBACK은 마지막 COMMIT 이후의 변경을 취소한다.","SAVEPOINT를 지정하면 특정 지점까지만 부분 롤백할 수 있다.","ROLLBACK으로 TRUNCATE로 삭제한 데이터도 복구할 수 있다."]'::jsonb, 3, 'TRUNCATE는 DDL로 자동 커밋되므로 ROLLBACK으로 복구할 수 없다. DELETE(DML)로 지운 데이터만 롤백 가능하다.', null::jsonb, '["TCL","SAVEPOINT","TRUNCATE"]'::jsonb),
  ('q057', 'sql', 'sql_management', 2, 'DELETE, TRUNCATE, DROP의 차이에 대한 설명으로 옳지 않은 것은?', '["DELETE는 DML로 WHERE 조건으로 일부 행만 지울 수 있고 롤백이 가능하다.","TRUNCATE는 DDL로 전체 행을 지우고 저장공간을 반납하며 롤백이 어렵다.","DROP은 테이블 구조 자체를 삭제한다.","TRUNCATE는 WHERE 조건으로 일부 행만 삭제할 수 있다."]'::jsonb, 3, 'TRUNCATE는 조건 없이 전체 행을 제거한다. WHERE로 일부만 지우는 것은 DELETE만 가능하다.', null::jsonb, '["DELETE","TRUNCATE","DROP"]'::jsonb),
  ('q058', 'sql', 'sql_management', 2, '제약조건에 대한 설명으로 옳지 않은 것은?', '["PRIMARY KEY는 유일성과 NOT NULL을 함께 보장한다.","UNIQUE 제약은 유일성을 보장하지만 NULL은 허용될 수 있다.","CHECK 제약은 컬럼 값이 특정 조건을 만족하도록 제한한다.","한 테이블에 PRIMARY KEY를 두 개 이상 만들 수 있다."]'::jsonb, 3, 'PRIMARY KEY는 테이블당 하나만 존재한다(복합키로 여러 컬럼을 묶을 수는 있음). 유일성 보장이 여러 개 필요하면 UNIQUE를 사용한다.', null::jsonb, '["제약조건","PK","UNIQUE"]'::jsonb),
  ('q059', 'sql', 'sql_management', 3, '외래키(FK) 참조 무결성 옵션에 대한 설명으로 옳지 않은 것은?', '["ON DELETE CASCADE: 부모 행 삭제 시 자식 행도 함께 삭제된다.","ON DELETE SET NULL: 부모 행 삭제 시 자식의 FK 값을 NULL로 만든다.","RESTRICT / NO ACTION: 자식이 존재하면 부모 삭제를 막는다.","CASCADE: 부모 행 삭제 시 자식은 그대로 두고 부모만 삭제한다."]'::jsonb, 3, 'CASCADE는 부모 삭제 시 참조하는 자식 행까지 연쇄 삭제한다. 자식을 남겨 두려면 SET NULL/SET DEFAULT 또는 삭제 제한(RESTRICT)을 사용한다.', null::jsonb, '["참조무결성","CASCADE","FK"]'::jsonb),
  ('q060', 'sql', 'sql_management', 2, '권한 관리(DCL)에 대한 설명으로 옳은 것은?', '["REVOKE는 권한을 부여하는 명령이다.","WITH GRANT OPTION으로 권한을 받은 사용자는 그 권한을 다른 사용자에게 다시 부여할 수 있다.","ROLE에는 권한을 담을 수 없다.","GRANT는 사용자를 삭제하는 명령이다."]'::jsonb, 1, 'GRANT=부여, REVOKE=회수, ROLE=권한 묶음. WITH GRANT OPTION은 권한을 받은 사용자가 다시 다른 사용자에게 그 권한을 부여할 수 있게 한다.', null::jsonb, '["DCL","GRANT","WITH GRANT OPTION"]'::jsonb),
  ('q061', 'sql', 'sql_advanced', 2, '다음 LEFT OUTER JOIN의 결과 행 수는? (아래 ''단계별 결과'' 참고)', '["3행","4행","5행","6행"]'::jsonb, 1, 'LEFT OUTER JOIN은 왼쪽(customer) 행을 모두 보존한다. Kim은 주문 2건, Lee는 1건, Park는 주문이 없어 amount가 NULL인 1행이 남는다. 2 + 1 + 1 = 4행.', '{"query":"SELECT c.name, o.amount FROM customer c LEFT JOIN orders o ON c.id = o.cust_id","steps":[{"clause":"FROM (customer)","desc":"왼쪽 테이블 customer.","table":{"columns":["id","name"],"data":[[1,"Kim"],[2,"Lee"],[3,"Park"]]}},{"clause":"orders (참조 테이블)","desc":"오른쪽 테이블 orders (cust_id가 customer.id를 참조).","table":{"columns":["id","cust_id","amount"],"data":[[10,1,500],[11,1,300],[12,2,700]]}},{"clause":"LEFT OUTER JOIN","desc":"c.id = o.cust_id 매칭. 왼쪽 행은 모두 보존 → Park는 짝이 없어 NULL.","table":{"columns":["name","amount"],"data":[["Kim",500],["Kim",300],["Lee",700],["Park",null]]}},{"clause":"SELECT","desc":"c.name, o.amount 출력 → 4행.","table":{"columns":["name","amount"],"data":[["Kim",500],["Kim",300],["Lee",700],["Park",null]]}}]}'::jsonb, '["OUTER JOIN","LEFT JOIN"]'::jsonb),
  ('q062', 'sql', 'sql_advanced', 3, '부서가 2개일 때 GROUP BY ROLLUP(dept)의 결과 행 수는? (단계별 결과 참고)', '["2행","3행","4행","5행"]'::jsonb, 1, 'ROLLUP(dept)는 부서별 소계에 ''전체 총계'' 1행을 더한다. 부서 2개 → 소계 2행 + 총계 1행 = 3행. 총계 행의 dept는 NULL로 표시된다.', '{"query":"SELECT dept, SUM(sal) FROM emp GROUP BY ROLLUP(dept)","steps":[{"clause":"FROM (emp)","desc":"emp 테이블을 읽는다.","table":{"columns":["name","dept","sal"],"data":[["Kim","SALES",300],["Lee","SALES",200],["Park","DEV",400]]}},{"clause":"GROUP BY dept","desc":"부서별로 SUM(sal) 집계.","table":{"columns":["dept","SUM(sal)"],"data":[["SALES",500],["DEV",400]]}},{"clause":"ROLLUP (총계 추가)","desc":"부서 소계에 전체 총계(dept=NULL) 1행을 더한다.","table":{"columns":["dept","SUM(sal)"],"data":[["SALES",500],["DEV",400],[null,900]]}},{"clause":"SELECT","desc":"최종 3행 (소계 2 + 총계 1).","table":{"columns":["dept","SUM(sal)"],"data":[["SALES",500],["DEV",400],[null,900]]}}]}'::jsonb, '["ROLLUP","그룹함수","소계"]'::jsonb),
  ('q063', 'sql', 'sql_advanced', 3, '다음 셀프 조인(사원-관리자)의 결과 행 수는? (단계별 결과 참고)', '["2행","3행","4행","5행"]'::jsonb, 1, 'e.mgr_id = m.id 로 자기 자신과 조인한다. mgr_id가 NULL인 Kim은 INNER JOIN 매칭에서 제외되고, 나머지 3명(Lee·Park·Han)만 관리자와 짝지어져 3행이 된다.', '{"query":"SELECT e.name AS emp, m.name AS mgr FROM emp e JOIN emp m ON e.mgr_id = m.id","steps":[{"clause":"FROM emp e (자기 자신)","desc":"동일 테이블을 사원(e) 관점으로 본다.","table":{"columns":["id","name","mgr_id"],"data":[[1,"Kim",null],[2,"Lee",1],[3,"Park",1],[4,"Han",2]]}},{"clause":"JOIN emp m ON e.mgr_id = m.id","desc":"관리자(m)와 매칭. Kim은 mgr_id가 NULL이라 짝이 없어 탈락.","table":{"columns":["emp","mgr"],"data":[["Lee","Kim"],["Park","Kim"],["Han","Lee"]]}},{"clause":"SELECT","desc":"사원-관리자 3쌍 출력 → 3행.","table":{"columns":["emp","mgr"],"data":[["Lee","Kim"],["Park","Kim"],["Han","Lee"]]}}]}'::jsonb, '["SELF JOIN","INNER JOIN"]'::jsonb),
  ('q064', 'sql', 'sql_advanced', 2, '두 조회 결과를 UNION 했을 때의 행 수는? (단계별 결과 참고)', '["2행","3행","4행","5행"]'::jsonb, 1, 'UNION은 두 집합을 합친 뒤 중복을 제거한다(정렬 수반). ''DEV''가 양쪽에 있어 하나로 합쳐져 SALES·DEV·HR 3행이 된다. UNION ALL이었다면 중복을 그대로 두어 4행.', '{"query":"SELECT job FROM emp WHERE dept=''SALES'' UNION SELECT job FROM emp WHERE dept=''DEV''","steps":[{"clause":"쿼리1 결과","desc":"SALES 부서의 job.","table":{"columns":["job"],"data":[["관리"],["영업"]]}},{"clause":"쿼리2 결과","desc":"DEV 부서의 job.","table":{"columns":["job"],"data":[["영업"],["개발"]]}},{"clause":"UNION ALL (단순 결합)","desc":"먼저 그냥 합치면 중복 ''영업'' 포함 4행.","table":{"columns":["job"],"data":[["관리"],["영업"],["영업"],["개발"]]}},{"clause":"UNION (중복 제거)","desc":"중복 ''영업''을 제거 → 3행.","table":{"columns":["job"],"data":[["관리"],["영업"],["개발"]]}}]}'::jsonb, '["집합연산","UNION","UNION ALL"]'::jsonb),
  ('q065', 'sql', 'sql_basics', 2, '다음 중 문법 오류가 있는 SQL은? (Oracle)', '["SELECT ename, sal*12 AS yearly FROM emp ORDER BY yearly","SELECT deptno, COUNT(*) FROM emp GROUP BY deptno HAVING COUNT(*) > 3","SELECT ename, sal*12 AS yearly FROM emp WHERE yearly > 30000","SELECT DISTINCT deptno FROM emp"]'::jsonb, 2, 'WHERE는 SELECT보다 먼저 실행되므로 SELECT에서 만든 별칭(yearly)을 WHERE에서 쓸 수 없다. `WHERE sal*12 > 30000`으로 써야 한다. 별칭은 ORDER BY에서만 사용 가능.', null::jsonb, '["기출유형","실행순서","ALIAS"]'::jsonb),
  ('q066', 'sql', 'sql_basics', 1, 'sal=300, comm=NULL인 사원에 대해 SELECT sal + comm 의 결과는?', '["300","0","NULL","오류"]'::jsonb, 2, 'NULL과의 산술 연산 결과는 NULL이다(0 아님). 300을 원하면 NVL(comm,0)로 감싸야 한다.', null::jsonb, '["기출유형","NULL"]'::jsonb),
  ('q067', 'sql', 'sql_basics', 2, 'comm에 NULL 4개를 포함한 emp 10행에서 결과가 6인 것은?', '["COUNT(*)","COUNT(comm)","SUM(comm) / AVG(comm)","COUNT(1)"]'::jsonb, 1, 'COUNT(컬럼)은 NULL을 제외하고 센다 → 10-4=6. COUNT(*), COUNT(1)은 전체 행 10.', null::jsonb, '["기출유형","COUNT","NULL"]'::jsonb),
  ('q068', 'sql', 'sql_basics', 2, 'NVL2(comm, sal+comm, sal) 의 의미로 옳은 것은?', '["comm이 NULL이면 sal+comm 반환","comm이 NOT NULL이면 sal+comm, NULL이면 sal 반환","항상 sal+comm 반환","comm이 NULL이면 오류"]'::jsonb, 1, 'NVL2(A,B,C)는 A가 NOT NULL이면 B, NULL이면 C. 즉 comm이 있으면 sal+comm, 없으면 sal.', null::jsonb, '["기출유형","NVL"]'::jsonb),
  ('q069', 'sql', 'sql_basics', 2, 'INSTR(''DATA-BASE'', ''-'') 의 결과는? (Oracle, 위치는 1부터)', '["4","5","6","0"]'::jsonb, 1, 'INSTR은 찾는 문자의 위치를 반환한다. D(1)A(2)T(3)A(4)-(5) → ''-''는 5번째.', null::jsonb, '["기출유형","문자함수","INSTR"]'::jsonb),
  ('q070', 'sql', 'sql_basics', 3, 'TRUNC(1278, -2) 의 결과는?', '["1200","1300","1278","1000"]'::jsonb, 0, 'TRUNC의 자리수가 음수면 정수부를 절사한다. -2는 백의 자리 아래를 버림 → 1200.', null::jsonb, '["기출유형","숫자함수","TRUNC"]'::jsonb),
  ('q071', 'sql', 'sql_basics', 2, '다음 중 결과가 옳지 않은 것은?', '["CEIL(3.2) = 4","FLOOR(3.8) = 3","CEIL(-2.5) = -2","FLOOR(-2.5) = -2"]'::jsonb, 3, 'FLOOR는 내림(−∞ 방향)이므로 FLOOR(-2.5) = -3이다. CEIL(-2.5)=-2는 옳다.', null::jsonb, '["기출유형","숫자함수","FLOOR"]'::jsonb),
  ('q072', 'sql', 'sql_basics', 2, 'CASE로는 되지만 Oracle DECODE로는 표현하기 어려운 것은?', '["특정 값과 ''같은지'' 비교","''범위''(>, <=) 조건 비교","컬럼 값을 그대로 반환","여러 값을 매핑"]'::jsonb, 1, 'DECODE는 ''='' 동등 비교만 가능하다. 범위 조건(>, <=)은 CASE로만 표현할 수 있다.', null::jsonb, '["기출유형","CASE","DECODE"]'::jsonb),
  ('q073', 'sql', 'sql_basics', 2, 'WHERE deptno=10 OR deptno=20 AND sal>300 은 어떻게 해석되는가?', '["(deptno=10 OR deptno=20) AND sal>300","deptno=10 OR (deptno=20 AND sal>300)","왼쪽부터 순서대로 평가","문법 오류"]'::jsonb, 1, 'AND가 OR보다 우선순위가 높다 → deptno=10 OR (deptno=20 AND sal>300).', null::jsonb, '["기출유형","연산자우선순위"]'::jsonb),
  ('q074', 'sql', 'sql_basics', 1, '전화번호가 ''02-''로 시작하는 행을 찾는 조건으로 옳은 것은?', '["WHERE tel LIKE ''02-%''","WHERE tel LIKE ''02_%''","WHERE tel = ''02-%''","WHERE tel LIKE ''%02-''"]'::jsonb, 0, '%는 0글자 이상. ''02-''로 시작 → LIKE ''02-%''. `_`는 한 글자, `=`는 와일드카드 미적용.', null::jsonb, '["기출유형","LIKE"]'::jsonb),
  ('q075', 'sql', 'sql_advanced', 2, 'salgrade(losal, hisal) 등급표와 emp를 sal이 losal~hisal 범위에 드는지로 조인하는 것은?', '["EQUI JOIN","NON-EQUI JOIN","SELF JOIN","CROSS JOIN"]'::jsonb, 1, '= 이 아닌 BETWEEN/부등호 조건으로 조인하면 NON-EQUI JOIN이다.', null::jsonb, '["기출유형","JOIN","NonEqui"]'::jsonb),
  ('q076', 'sql', 'sql_advanced', 3, 'Oracle 전통 문법에서 emp를 모두 보존하는 LEFT OUTER JOIN 표기는? (emp e, dept d)', '["WHERE e.deptno = d.deptno(+)","WHERE e.deptno(+) = d.deptno","WHERE e.deptno(+) = d.deptno(+)","WHERE e.deptno = d.deptno"]'::jsonb, 0, '(+)는 NULL로 채워지는 ''부족한'' 쪽에 붙인다. 오른쪽 d에 (+)를 붙이면 왼쪽 emp가 모두 보존된다(=LEFT OUTER).', null::jsonb, '["기출유형","OUTER JOIN"]'::jsonb),
  ('q077', 'sql', 'sql_advanced', 2, '서브쿼리가 여러 행을 반환할 때 ''=''를 쓰면 오류다. 대신 사용할 수 있는 것은?', '["IN","BETWEEN","LIKE","= 를 그대로 사용"]'::jsonb, 0, '다중행 서브쿼리에는 IN, ANY, ALL, EXISTS 같은 다중행 연산자를 써야 한다. 단일행 ''=''는 오류.', null::jsonb, '["기출유형","서브쿼리","다중행"]'::jsonb),
  ('q078', 'sql', 'sql_advanced', 3, 'sal < ANY (SELECT sal FROM emp WHERE deptno=30) 의 의미로 옳은 것은?', '["30번 부서 최솟값보다 작아야 참","30번 부서 최댓값보다 작으면 참","30번 부서 평균보다 작아야 참","항상 거짓"]'::jsonb, 1, '< ANY는 집합의 어느 하나보다 작으면 참 → ''최댓값''보다 작으면 된다. 반대로 < ALL은 ''최솟값''보다 작아야 한다.', null::jsonb, '["기출유형","ANY","ALL"]'::jsonb),
  ('q079', 'sql', 'sql_advanced', 2, 'EXISTS 서브쿼리에 대한 설명으로 옳은 것은?', '["서브쿼리가 반환한 값을 메인쿼리와 크기 비교한다.","행의 존재 여부만 판단하며, 존재가 확인되면 더 찾지 않고 참을 반환한다.","반드시 단일 행만 반환해야 한다.","NOT EXISTS는 문법상 사용할 수 없다."]'::jsonb, 1, 'EXISTS는 결과 행이 하나라도 있으면 참(값은 비교하지 않음). 존재만 확인하면 되므로 조기 종료가 가능하다.', null::jsonb, '["기출유형","EXISTS"]'::jsonb),
  ('q080', 'sql', 'sql_advanced', 2, 'UNION과 UNION ALL의 차이로 옳지 않은 것은?', '["UNION은 중복을 제거한다.","UNION ALL은 중복을 유지한다.","UNION은 정렬 부하가 있을 수 있다.","UNION ALL은 두 쿼리의 컬럼 개수가 달라도 동작한다."]'::jsonb, 3, '집합 연산은 두 쿼리의 컬럼 개수·타입이 호환되어야 한다. 개수가 다르면 오류.', null::jsonb, '["기출유형","집합연산","UNION"]'::jsonb),
  ('q081', 'sql', 'sql_advanced', 2, 'A={1,2,3,4}, B={2,4,6} 일 때 A MINUS B 의 결과는?', '["{1, 3}","{2, 4}","{1, 2, 3, 4, 6}","{6}"]'::jsonb, 0, 'MINUS는 차집합(A에는 있고 B에는 없는 것). {1,2,3,4}에서 2,4를 빼면 {1,3}.', null::jsonb, '["기출유형","MINUS"]'::jsonb),
  ('q082', 'sql', 'sql_advanced', 3, 'GROUP BY CUBE(a, b) 가 만드는 소계 조합으로 옳은 것은?', '["(a,b), (a), ()","(a,b), (a), (b), ()","(a,b) 만","() 만"]'::jsonb, 1, 'CUBE는 모든 조합의 소계를 만든다: (a,b),(a),(b),(). ROLLUP은 (a,b),(a),()의 일방향만.', null::jsonb, '["기출유형","CUBE","ROLLUP"]'::jsonb),
  ('q083', 'sql', 'sql_advanced', 2, '점수 [90, 90, 80, 70]에 대한 RANK()와 DENSE_RANK() 결과 쌍으로 옳은 것은? (단계별 결과 참고)', '["RANK 1,1,3,4 / DENSE 1,1,2,3","RANK 1,1,2,3 / DENSE 1,1,3,4","RANK 1,2,3,4 / DENSE 1,2,3,4","RANK 1,1,3,3 / DENSE 1,1,2,2"]'::jsonb, 0, 'RANK는 동순위 뒤 순위를 건너뛰어 1,1,3,4. DENSE_RANK는 건너뛰지 않아 1,1,2,3.', '{"query":"SELECT name, score, RANK() OVER(ORDER BY score DESC) rnk, DENSE_RANK() OVER(ORDER BY score DESC) drnk FROM t","steps":[{"clause":"FROM (t)","desc":"대상 데이터.","table":{"columns":["name","score"],"data":[["A",90],["B",90],["C",80],["D",70]]}},{"clause":"ORDER BY score DESC","desc":"점수 내림차순 정렬(동점은 그대로).","table":{"columns":["name","score"],"data":[["A",90],["B",90],["C",80],["D",70]]}},{"clause":"RANK / DENSE_RANK","desc":"동점(90,90)은 같은 순위. RANK는 다음을 3으로 건너뛰고, DENSE_RANK는 2로 이어감.","table":{"columns":["name","score","RANK","DENSE_RANK"],"data":[["A",90,1,1],["B",90,1,1],["C",80,3,2],["D",70,4,3]]}}]}'::jsonb, '["기출유형","윈도우함수","RANK"]'::jsonb),
  ('q084', 'sql', 'sql_advanced', 2, 'LAG(sal, 1, 0) OVER(ORDER BY hiredate) 의 의미로 옳은 것은?', '["다음 행의 sal, 없으면 0","이전 행의 sal, 없으면 0","현재 행의 sal","최초 행의 sal"]'::jsonb, 1, 'LAG는 현재 행보다 앞선(이전) 행 값을 가져온다. 세 번째 인자(0)는 대상이 없을 때의 기본값. (다음 행은 LEAD)', null::jsonb, '["기출유형","윈도우함수","LAG"]'::jsonb),
  ('q085', 'sql', 'sql_advanced', 3, 'NTILE(4) OVER(ORDER BY sal DESC) 의 의미로 옳은 것은?', '["급여 상위 4명만 반환한다.","급여 순으로 4개 그룹으로 균등 분할해 1~4를 부여한다.","4번째 행만 반환한다.","4명씩 끊어 최대 4개까지만 만든다."]'::jsonb, 1, 'NTILE(n)은 정렬된 행을 n개 그룹으로 최대한 균등 분할하고 각 행에 그룹 번호(1~n)를 부여한다.', null::jsonb, '["기출유형","윈도우함수","NTILE"]'::jsonb),
  ('q086', 'sql', 'sql_advanced', 3, '전체 급여 상위 5명을 구하는 올바른 쿼리는? (Oracle)', '["SELECT * FROM emp WHERE ROWNUM <= 5 ORDER BY sal DESC","SELECT * FROM (SELECT * FROM emp ORDER BY sal DESC) WHERE ROWNUM <= 5","SELECT TOP 5 * FROM emp ORDER BY sal DESC","SELECT * FROM emp ORDER BY sal DESC LIMIT 5"]'::jsonb, 1, 'ROWNUM은 정렬 전에 부여되므로 인라인 뷰로 먼저 정렬한 뒤 바깥에서 잘라야 한다. TOP은 SQL Server, LIMIT은 MySQL 문법.', null::jsonb, '["기출유형","ROWNUM","TopN"]'::jsonb),
  ('q087', 'sql', 'sql_advanced', 2, '계층형 질의의 의사컬럼 LEVEL에 대한 설명으로 옳은 것은?', '["루트가 0이다.","루트가 1이며 자식으로 내려갈수록 1씩 증가한다.","잎(리프) 노드가 1이다.","정렬 순서를 의미한다."]'::jsonb, 1, 'LEVEL은 계층 깊이를 나타내며 루트가 1, 하위로 갈수록 증가한다.', null::jsonb, '["기출유형","계층쿼리","LEVEL"]'::jsonb),
  ('q088', 'sql', 'sql_advanced', 2, '인라인 뷰(Inline View)에 대한 설명으로 옳은 것은?', '["SELECT 절에 위치하는 단일 값 서브쿼리다.","FROM 절에 위치하며 임시 결과 집합처럼 사용한다.","WHERE 절에만 위치한다.","미리 CREATE VIEW로 만들어 두어야 한다."]'::jsonb, 1, '인라인 뷰는 FROM 절에 오는 서브쿼리로, 질의 안에서만 쓰는 임시 뷰처럼 동작한다(객체 생성 불필요).', null::jsonb, '["기출유형","인라인뷰","서브쿼리"]'::jsonb),
  ('q089', 'sql', 'sql_management', 2, 'WHERE 조건으로 일부 행만 삭제할 수 있고 ROLLBACK으로 복구 가능한 명령은?', '["TRUNCATE","DELETE","DROP","TRUNCATE와 DROP"]'::jsonb, 1, 'DELETE는 DML로 WHERE로 일부만 삭제, 롤백 가능. TRUNCATE는 DDL(전체 삭제·자동커밋·롤백 불가), DROP은 구조 삭제.', null::jsonb, '["기출유형","DELETE","TRUNCATE"]'::jsonb),
  ('q090', 'sql', 'sql_management', 2, '소스와 비교해 일치하면 UPDATE, 없으면 INSERT를 한 문장으로 수행하는 것은?', '["UPSERT","MERGE","REPLACE","UNION"]'::jsonb, 1, 'MERGE 문이 WHEN MATCHED(UPDATE)와 WHEN NOT MATCHED(INSERT)를 한 번에 처리한다.', null::jsonb, '["기출유형","MERGE"]'::jsonb),
  ('q091', 'sql', 'sql_management', 2, '부모 행 삭제 시 이를 참조하는 자식 행도 함께 삭제되게 하는 FK 옵션은?', '["ON DELETE SET NULL","ON DELETE CASCADE","ON DELETE RESTRICT","ON DELETE NO ACTION"]'::jsonb, 1, 'ON DELETE CASCADE는 부모 삭제 시 자식까지 연쇄 삭제한다. SET NULL은 FK를 NULL로, RESTRICT/NO ACTION은 삭제를 막는다.', null::jsonb, '["기출유형","참조무결성","CASCADE"]'::jsonb),
  ('q092', 'data_modeling', 'modeling_basics', 2, '내부 스키마가 변경되어도 개념·외부 스키마에 영향이 없는 성질은?', '["논리적 독립성","물리적 독립성","개념적 독립성","구조적 독립성"]'::jsonb, 1, '물리적 독립성 = 내부(저장) 스키마 변경이 개념/외부에 영향 없음. 논리적 독립성 = 개념 변경이 외부에 영향 없음.', null::jsonb, '["기출유형","3층스키마","데이터독립성"]'::jsonb),
  ('q093', 'data_modeling', 'modeling_basics', 2, '복합키의 일부에만 종속되는 속성을 분리하는 정규화 단계는?', '["제1정규형","제2정규형","제3정규형","BCNF"]'::jsonb, 1, '제2정규형(2NF)은 부분 함수 종속(복합키 일부에만 종속)을 제거한다. 3NF는 이행 종속 제거.', null::jsonb, '["기출유형","정규화"]'::jsonb),
  ('q094', 'data_modeling', 'modeling_performance', 2, '반정규화(De-normalization)에 대한 설명으로 옳은 것은?', '["조회·입력·수정·삭제 모든 성능이 향상된다.","중복을 허용해 조회 성능을 높이지만 정합성 관리 부담이 커진다.","정규화의 다른 이름이다.","데이터 모델의 유연성이 높아진다."]'::jsonb, 1, '반정규화는 중복·통합으로 조회 성능을 높이는 대신, 입력·수정·삭제 부담과 정합성 관리 부담이 커지고 유연성은 낮아진다.', null::jsonb, '["기출유형","반정규화"]'::jsonb),
  ('q095', 'sql', 'sql_basics', 1, 'Oracle에서 상수나 함수 결과 하나만 조회할 때 사용하는 가상 테이블은?', '["DUAL","SYS","ROOT","TEMP"]'::jsonb, 0, 'Oracle의 DUAL은 1행 1열짜리 더미 테이블로, `SELECT SYSDATE FROM DUAL`처럼 단일 값 조회에 쓴다.', null::jsonb, '["기출유형","DUAL"]'::jsonb),
  ('q096', 'sql', 'sql_basics', 2, 'SELECT ''SQL'' || ''D'' || 2026 FROM dual 의 결과는? (Oracle)', '["SQLD2026","SQL D 2026","오류(숫자는 연결 불가)","SQLD 2026"]'::jsonb, 0, '|| 연결 시 숫자 2026은 문자로 자동 형변환되어 ''SQLD2026''이 된다.', null::jsonb, '["기출유형","합성연산자"]'::jsonb),
  ('q097', 'sql', 'sql_basics', 1, 'TO_CHAR(SYSDATE, ''YYYY-MM-DD'') 의 용도로 옳은 것은?', '["날짜를 지정한 형식의 문자열로 변환","문자를 날짜로 변환","숫자를 날짜로 변환","날짜를 숫자로 변환"]'::jsonb, 0, 'TO_CHAR는 날짜/숫자를 지정 포맷의 문자로 변환한다. 문자→날짜는 TO_DATE, 문자→숫자는 TO_NUMBER.', null::jsonb, '["기출유형","변환함수","TO_CHAR"]'::jsonb),
  ('q098', 'sql', 'sql_basics', 2, 'Oracle에서 (SYSDATE - hiredate) 연산의 결과 단위는?', '["일(days)","시간","월","초"]'::jsonb, 0, 'DATE 간 뺄셈의 결과는 ''일'' 단위의 숫자다. 개월 차이는 MONTHS_BETWEEN을 쓴다.', null::jsonb, '["기출유형","날짜함수"]'::jsonb),
  ('q099', 'sql', 'sql_basics', 1, 'GREATEST(10, 30, 20) 의 결과는?', '["30","10","20","60"]'::jsonb, 0, 'GREATEST는 인자 중 최댓값을 반환한다(최솟값은 LEAST).', null::jsonb, '["기출유형","숫자함수","GREATEST"]'::jsonb),
  ('q100', 'sql', 'sql_basics', 2, 'ORDER BY comm DESC NULLS LAST 의 의미로 옳은 것은?', '["comm 내림차순 정렬하되 NULL은 맨 뒤로 보낸다","NULL을 맨 앞으로 보낸다","오름차순 정렬한다","문법 오류다"]'::jsonb, 0, 'NULLS LAST는 NULL을 정렬 결과의 맨 뒤에 둔다. 기본적으로 DESC는 NULL이 앞에 오므로 명시적으로 뒤로 보낸 것.', null::jsonb, '["기출유형","ORDER BY","NULL"]'::jsonb),
  ('q101', 'sql', 'sql_basics', 1, 'WHERE deptno IN (10, 20, 30) 과 동일한 조건은?', '["deptno=10 OR deptno=20 OR deptno=30","deptno=10 AND deptno=20 AND deptno=30","deptno BETWEEN 10 AND 30","deptno=10"]'::jsonb, 0, 'IN은 OR의 축약형이다. 하나라도 일치하면 참.', null::jsonb, '["기출유형","IN"]'::jsonb),
  ('q102', 'sql', 'sql_basics', 3, '컬럼값에 실제 밑줄(''_'')이 포함된 행을 찾으려 한다. 올바른 조건은?', '["WHERE col LIKE ''%_%''","WHERE col LIKE ''%\\_%'' ESCAPE ''\\''","WHERE col = ''_''","WHERE col LIKE ''%__%''"]'::jsonb, 1, '_는 와일드카드(한 글자)이므로 리터럴로 찾으려면 ESCAPE 문자를 지정해 `\_`처럼 이스케이프해야 한다.', null::jsonb, '["기출유형","LIKE","ESCAPE"]'::jsonb),
  ('q103', 'sql', 'sql_basics', 2, '단순 CASE 식 `CASE deptno WHEN 10 THEN ''A'' WHEN 20 THEN ''B'' END` 의 결과로 옳은 것은?', '["deptno=10이면 ''A'', 20이면 ''B'', 그 외에는 NULL","항상 ''A''","범위 비교를 수행","ELSE가 없어 문법 오류"]'::jsonb, 0, 'ELSE가 없으면 어떤 WHEN에도 맞지 않을 때 NULL을 반환한다(오류 아님).', null::jsonb, '["기출유형","CASE"]'::jsonb),
  ('q104', 'sql', 'sql_basics', 2, 'SUM(DISTINCT sal) 에 대한 설명으로 옳은 것은?', '["중복된 급여 값은 한 번만 더한다","모든 급여를 그대로 더한다","NULL도 0으로 더한다","문법 오류다"]'::jsonb, 0, 'DISTINCT를 붙이면 중복 값을 제거한 뒤 집계한다. NULL은 여전히 제외된다.', null::jsonb, '["기출유형","집계함수","DISTINCT"]'::jsonb),
  ('q105', 'sql', 'sql_advanced', 3, 'GROUP BY GROUPING SETS((a,b),(a),()) 이 만드는 결과로 옳은 것은?', '["(a,b) 소계, (a) 소계, 전체 총계","(a,b) 조합만","모든 조합의 소계","문법 오류"]'::jsonb, 0, 'GROUPING SETS는 명시한 그룹 집합의 소계만 만든다. ()는 전체 총계.', null::jsonb, '["기출유형","GROUPING SETS"]'::jsonb),
  ('q106', 'sql', 'sql_advanced', 3, 'ROLLUP/CUBE 결과에서 특정 행이 소계(집계) 행인지 판별하는 함수는?', '["GROUPING()","GROUP_ID()","RANK()","DECODE()"]'::jsonb, 0, 'GROUPING(col)은 해당 컬럼이 소계로 집계되어 NULL이면 1, 아니면 0을 반환한다.', null::jsonb, '["기출유형","GROUPING","ROLLUP"]'::jsonb),
  ('q107', 'sql', 'sql_advanced', 3, 'SUM(sal) OVER (ORDER BY hiredate ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) 의 의미는?', '["입사일 순서대로의 누적 합계","전체 급여 합계","현재 행의 급여","다음 행까지의 합계"]'::jsonb, 0, '프레임이 ''처음부터 현재 행까지''이므로 정렬 순서에 따른 누적합(running total)이 된다.', null::jsonb, '["기출유형","윈도우함수","누적합"]'::jsonb),
  ('q108', 'sql', 'sql_advanced', 2, '각 부서에서 급여 1위 사원만 남기려 할 때 가장 적합한 것은?', '["ROW_NUMBER() OVER(PARTITION BY deptno ORDER BY sal DESC) 로 순번을 매겨 1인 행만","COUNT(*) 사용","WHERE ROWNUM = 1","DISTINCT deptno"]'::jsonb, 0, 'PARTITION BY deptno로 부서별 그룹을 만들고 급여 내림차순 ROW_NUMBER가 1인 행을 고르면 부서별 최고 급여자만 남는다.', null::jsonb, '["기출유형","윈도우함수","ROW_NUMBER"]'::jsonb),
  ('q109', 'sql', 'sql_advanced', 2, 'FIRST_VALUE(ename) OVER(PARTITION BY deptno ORDER BY sal DESC) 의 의미로 옳은 것은?', '["부서별 급여가 가장 높은 사원의 이름","부서별 급여가 가장 낮은 사원의 이름","전체에서 가장 높은 사원","현재 행의 이름"]'::jsonb, 0, '급여 내림차순 정렬 파티션의 첫 값이므로 부서별 최고 급여자 이름이다.', null::jsonb, '["기출유형","윈도우함수","FIRST_VALUE"]'::jsonb),
  ('q110', 'sql', 'sql_advanced', 3, '서브쿼리 결과에 NULL이 섞여 있을 때 WHERE x NOT IN (서브쿼리) 의 위험으로 옳은 것은?', '["NULL 때문에 조건이 UNKNOWN이 되어 결과가 한 건도 안 나올 수 있다","항상 전체 행을 반환한다","즉시 오류가 난다","NULL을 무시하고 정상 동작한다"]'::jsonb, 0, 'NOT IN 목록에 NULL이 있으면 비교가 UNKNOWN이 되어 참인 행이 사라질 수 있다. 안전하게는 NOT EXISTS를 쓴다.', null::jsonb, '["기출유형","NOT IN","NULL"]'::jsonb),
  ('q111', 'sql', 'sql_advanced', 2, 'SELECT ename, (SELECT dname FROM dept WHERE deptno=e.deptno) FROM emp e 에서 서브쿼리가 2행 이상 반환하면?', '["오류가 난다(스칼라 서브쿼리는 단일 값이어야 함)","첫 행만 반환한다","마지막 행만 반환한다","NULL을 반환한다"]'::jsonb, 0, '스칼라 서브쿼리는 1행 1컬럼(단일 값)을 반환해야 하며, 2행 이상이면 ''single-row subquery returns more than one row'' 오류.', null::jsonb, '["기출유형","스칼라서브쿼리"]'::jsonb),
  ('q112', 'sql', 'sql_advanced', 2, 'FULL OUTER JOIN에 대한 설명으로 옳은 것은?', '["양쪽 테이블의 매칭되지 않는 행까지 모두 보존한다","왼쪽 테이블만 보존한다","교집합만 반환한다","두 테이블의 모든 조합(카티션 곱)을 만든다"]'::jsonb, 0, 'FULL OUTER JOIN = LEFT + RIGHT. 양쪽의 미매칭 행을 모두 남기고 반대편은 NULL로 채운다.', null::jsonb, '["기출유형","OUTER JOIN"]'::jsonb),
  ('q113', 'sql', 'sql_advanced', 2, '동명 컬럼 deptno로 조인하는 `emp JOIN dept USING (deptno)` 에 대한 설명으로 옳은 것은?', '["USING에 쓴 공통 컬럼에는 테이블 접두사를 붙이면 안 된다","반드시 ON 절과 함께 써야 한다","컬럼명이 서로 달라도 된다","결과가 CROSS JOIN이 된다"]'::jsonb, 0, 'USING 절의 공통 컬럼은 하나로 합쳐지므로 `deptno`처럼 접두사 없이 참조해야 한다(e.deptno 오류).', null::jsonb, '["기출유형","JOIN","USING"]'::jsonb),
  ('q114', 'sql', 'sql_advanced', 2, '계층형 질의에서 CONNECT_BY_ISLEAF = 1 인 행의 의미로 옳은 것은?', '["더 이상 자식이 없는 최하위(잎) 노드","루트 노드","중간 노드","순환이 발생한 노드"]'::jsonb, 0, 'CONNECT_BY_ISLEAF는 자식이 없으면 1, 있으면 0. 즉 1이면 리프 노드.', null::jsonb, '["기출유형","계층쿼리","CONNECT_BY_ISLEAF"]'::jsonb),
  ('q115', 'sql', 'sql_advanced', 3, '각 사원의 급여가 ''부서 급여 합계''에서 차지하는 비율을 구할 때 분모로 적합한 것은?', '["SUM(sal) OVER (PARTITION BY deptno)","SUM(sal)","COUNT(*) OVER ()","sal"]'::jsonb, 0, '윈도우 함수 SUM(sal) OVER(PARTITION BY deptno)는 행을 줄이지 않고 각 행에 ''그 부서의 급여 합''을 붙여 주므로 비율 계산의 분모로 알맞다.', null::jsonb, '["기출유형","윈도우함수","PARTITION BY"]'::jsonb),
  ('q116', 'sql', 'sql_advanced', 3, '정렬된 결과의 11~20번째 행(2페이지)을 구하려 한다. Oracle ROWNUM으로 옳은 접근은?', '["정렬·ROWNUM을 인라인 뷰로 감싸 별칭을 만든 뒤 그 별칭으로 11~20 범위를 필터","WHERE ROWNUM BETWEEN 11 AND 20 을 직접 사용","SELECT TOP 20 ... OFFSET 10","LIMIT 10 OFFSET 10"]'::jsonb, 0, 'ROWNUM은 1부터 매겨지며 `>1` 직접 비교가 안 되므로, 인라인 뷰에서 ROWNUM을 별칭(rn)으로 고정한 뒤 바깥에서 rn BETWEEN 11 AND 20으로 잘라야 한다.', null::jsonb, '["기출유형","ROWNUM","페이징"]'::jsonb),
  ('q117', 'sql', 'sql_advanced', 2, 'UNION으로 합친 결과 전체를 정렬할 때 ORDER BY의 위치로 옳은 것은?', '["가장 마지막 SELECT 뒤에 한 번만 작성","각 SELECT마다 작성","첫 SELECT에만 작성","UNION 앞에 작성"]'::jsonb, 0, '집합 연산의 ORDER BY는 전체 결과에 대해 맨 마지막에 한 번만 쓴다.', null::jsonb, '["기출유형","집합연산","ORDER BY"]'::jsonb),
  ('q118', 'sql', 'sql_advanced', 2, '뷰(VIEW)에 대한 설명으로 옳지 않은 것은?', '["복잡한 질의에 이름을 붙여 재사용할 수 있다","특정 컬럼만 노출해 보안에 활용할 수 있다","논리적 독립성을 높인다","뷰는 항상 데이터를 물리적으로 저장한다"]'::jsonb, 3, '일반 뷰는 질의 정의만 저장할 뿐 데이터를 물리적으로 저장하지 않는다(물리 저장은 Materialized View).', null::jsonb, '["기출유형","VIEW"]'::jsonb),
  ('q119', 'sql', 'sql_management', 2, 'CREATE TABLE의 제약조건 정의에 대한 설명으로 옳은 것은?', '["여러 컬럼으로 구성된 복합 기본키는 테이블 레벨로 정의한다","NOT NULL은 테이블 레벨로만 지정 가능하다","CHECK는 컬럼 레벨에 지정할 수 없다","PK는 컬럼 레벨로만 지정 가능하다"]'::jsonb, 0, '복합키(여러 컬럼) PK는 컬럼 레벨로 표현할 수 없어 테이블 레벨 `PRIMARY KEY(a,b)`로 정의한다. NOT NULL은 컬럼 레벨 전용.', null::jsonb, '["기출유형","제약조건","DDL"]'::jsonb),
  ('q120', 'sql', 'sql_management', 2, 'Oracle에서 기존 컬럼의 데이터 타입/크기를 변경하는 구문은?', '["ALTER TABLE t MODIFY (col NUMBER(10))","ALTER TABLE t CHANGE col ...","ALTER TABLE t ALTER col ...","UPDATE TABLE t SET TYPE ..."]'::jsonb, 0, 'Oracle은 컬럼 변경에 MODIFY를 쓴다(추가는 ADD, 삭제는 DROP COLUMN, 이름변경은 RENAME COLUMN).', null::jsonb, '["기출유형","ALTER","DDL"]'::jsonb),
  ('q121', 'sql', 'sql_management', 2, '대량 행을 모두 삭제하면서 저장 공간을 즉시 반납하고 로그 부담이 적어 빠른 명령은?', '["TRUNCATE","DELETE","UPDATE","SELECT"]'::jsonb, 0, 'TRUNCATE는 전체 행을 빠르게 제거하고 공간을 반납한다(단 DDL이라 롤백 불가). 조건부 삭제는 DELETE.', null::jsonb, '["기출유형","TRUNCATE","DELETE"]'::jsonb),
  ('q122', 'sql', 'sql_management', 2, '여러 권한을 묶은 ROLE을 만들어 사용자에게 부여하는 순서로 옳은 것은?', '["CREATE ROLE → GRANT 권한 TO 롤 → GRANT 롤 TO 사용자","GRANT 롤 TO 사용자 → CREATE ROLE","ROLE에는 권한을 담을 수 없다","REVOKE로 권한을 부여한다"]'::jsonb, 0, '롤을 생성(CREATE ROLE)하고 권한을 롤에 부여한 뒤(GRANT ... TO 롤), 그 롤을 사용자에게 부여(GRANT 롤 TO 사용자)한다.', null::jsonb, '["기출유형","DCL","ROLE"]'::jsonb),
  ('q123', 'data_modeling', 'modeling_basics', 2, '두 엔터티 간 M:N 관계를 물리 모델로 구현할 때 일반적으로 필요한 것은?', '["교차(연관) 엔터티를 두어 1:M 관계 두 개로 분해","관계를 그대로 M:N으로 둔다","한쪽 엔터티를 삭제한다","두 엔터티를 하나로 통합한다"]'::jsonb, 0, '관계형 DB는 M:N을 직접 표현하기 어려워, 교차(연관) 엔터티를 두어 1:M 두 개로 해소한다.', null::jsonb, '["기출유형","관계","교차엔터티"]'::jsonb),
  ('q124', 'data_modeling', 'modeling_performance', 2, '대량 데이터를 인스턴스(행) 단위로 나눠 저장·관리하는 물리 기법은?', '["수평 분할(파티셔닝)","수직 분할","정규화","인덱스 생성"]'::jsonb, 0, '행(인스턴스) 기준으로 나누는 것은 수평 분할(파티셔닝), 컬럼 기준으로 나누는 것은 수직 분할이다.', null::jsonb, '["기출유형","반정규화","파티셔닝"]'::jsonb)
